package com.weearntogether.play

import android.app.Activity
import android.app.AlertDialog
import android.os.Bundle
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.view.Gravity
import android.view.View
import android.widget.*

class MainActivity : Activity() {
    private val navy=Color.rgb(6,12,31); private val panel=Color.rgb(17,27,58); private val panel2=Color.rgb(27,39,78); private val purple=Color.rgb(112,67,232); private val blue=Color.rgb(25,126,242); private val gold=Color.rgb(255,198,65)
    private lateinit var root:LinearLayout
    private val loyalty by lazy{LoyaltyProgress(this)}; private val playHistory by lazy{PlayHistory(this)}; private val profile by lazy{getSharedPreferences("wet_guest_profile",MODE_PRIVATE)}
    private var levelPlay:LevelPlayManager?=null
    private fun tr(s:String)=AppLocale.t(s)
    override fun onCreate(savedInstanceState:Bundle?){super.onCreate(savedInstanceState);if(profile.contains("guest_id")){initAds();home()}else welcome()}
    private fun initAds(){if(levelPlay!=null)return;val id=profile.getString("guest_id",null)?:return;levelPlay=LevelPlayManager(this,id);levelPlay?.initialize()}
    private fun rounded(color:Int,r:Float)=GradientDrawable().apply{setColor(color);cornerRadius=r}
    private fun gradient()=GradientDrawable(GradientDrawable.Orientation.LEFT_RIGHT,intArrayOf(purple,blue)).apply{cornerRadius=30f}
    private fun screen(title:String=""){root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(22,28,22,30);setBackgroundColor(navy)};setContentView(ScrollView(this).apply{isFillViewport=true;addView(root)});if(title.isNotEmpty())heading(title,30)}
    private fun heading(s:String,size:Int=22,color:Int=Color.WHITE){root.addView(TextView(this).apply{text=s;textSize=size.toFloat();setTextColor(color);setTypeface(null,Typeface.BOLD);setPadding(3,10,3,10)})}
    private fun label(s:String,size:Int=15,color:Int=0xffbdc8e7.toInt()){root.addView(TextView(this).apply{text=s;textSize=size.toFloat();setTextColor(color);setPadding(3,5,3,9)})}
    private fun button(label:String,action:()->Unit){root.addView(Button(this).apply{text=label;textSize=16f;isAllCaps=false;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE);background=gradient();minHeight=0;minimumHeight=0;setOnClickListener{action()}},LinearLayout.LayoutParams(-1,112).apply{bottomMargin=14})}
    private fun section(title:String){heading(title,15,gold)}
    private fun hero(){val h=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;gravity=Gravity.CENTER_HORIZONTAL;setPadding(28,28,28,28);background=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(0xff4b2398.toInt(),0xff0d7bd8.toInt(),0xff071b42.toInt())).apply{cornerRadius=42f}};h.addView(TextView(this).apply{text=tr("SEASON QUEST");textSize=13f;setTextColor(gold);setTypeface(null,Typeface.BOLD)});h.addView(TextView(this).apply{text=tr("PLAY. LEVEL UP. COLLECT.");textSize=27f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);gravity=Gravity.CENTER;setPadding(0,10,0,8)});h.addView(TextView(this).apply{text=tr("Complete game missions and grow your loyalty balance.");textSize=15f;setTextColor(0xffd7e5ff.toInt());gravity=Gravity.CENTER});h.addView(Button(this).apply{text=tr("VIEW QUESTS");isAllCaps=false;setTypeface(null,Typeface.BOLD);setTextColor(navy);background=rounded(gold,26f);setOnClickListener{gamesHub()}},LinearLayout.LayoutParams(-1,104).apply{topMargin=20});root.addView(h,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=20})}
    private fun stats(){val box=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;background=rounded(panel,32f);setPadding(10,17,10,17)};fun add(v:String,l:String,c:Int){box.addView(TextView(this).apply{text="$v\n${tr(l)}";gravity=Gravity.CENTER;textSize=15f;setTextColor(c);setTypeface(null,Typeface.BOLD)},LinearLayout.LayoutParams(0,86,1f))};add(loyalty.points.toString(),"LOYALTY",gold);add(loyalty.currentStreak.toString(),"STREAK",Color.WHITE);add("${loyalty.todayGames}/${loyalty.dailyGoal}","TODAY",Color.WHITE);root.addView(box,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=20})}
    private fun missionCard(title:String,desc:String,category:String,progress:Int,target:Int,action:()->Unit){val p=progress.coerceIn(0,target);val box=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(24,20,24,20);background=rounded(panel,34f)};val top=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};val words=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};words.addView(TextView(this).apply{text=category;textSize=12f;setTextColor(gold);setTypeface(null,Typeface.BOLD)});words.addView(TextView(this).apply{text=title;textSize=22f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);setPadding(0,5,0,3)});words.addView(TextView(this).apply{text=tr(desc);textSize=14f;setTextColor(0xffc5d1ef.toInt());maxLines=2});top.addView(words,LinearLayout.LayoutParams(0,-2,1f));top.addView(Button(this).apply{text=tr(if(p>=target) "PLAY AGAIN" else "PLAY");isAllCaps=false;setTypeface(null,Typeface.BOLD);setTextColor(Color.WHITE);background=gradient();minHeight=0;minimumHeight=0;setOnClickListener{showMission(title,desc,target,action)}},LinearLayout.LayoutParams(190,92));box.addView(top);box.addView(ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal).apply{max=target;this.progress=p},LinearLayout.LayoutParams(-1,24).apply{topMargin=15});box.addView(TextView(this).apply{text=if(p>=target) tr("MISSION COMPLETE") else "$p/$target";gravity=Gravity.END;textSize=12f;setTextColor(if(p>=target) gold else 0xffaab8dc.toInt());setTypeface(null,Typeface.BOLD)});root.addView(box,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=15})}
    private fun showMission(title:String,desc:String,target:Int,action:()->Unit){val wrap=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(38,28,38,18)};wrap.addView(TextView(this).apply{text=title;textSize=24f;setTypeface(null,Typeface.BOLD);setTextColor(0xff20243a.toInt());gravity=Gravity.CENTER});wrap.addView(TextView(this).apply{text=tr(desc);textSize=16f;setTextColor(0xff555b70.toInt());gravity=Gravity.CENTER;setPadding(0,14,0,10)});wrap.addView(TextView(this).apply{text=tr("MISSION: PLAY $target SESSIONS");textSize=15f;setTextColor(0xff6a46d8.toInt());setTypeface(null,Typeface.BOLD);gravity=Gravity.CENTER;setPadding(0,8,0,14)});val dialog=AlertDialog.Builder(this).setView(wrap).setNegativeButton(tr("NOT NOW"),null).setPositiveButton(tr("CONTINUE")){_,_->action()}.create();dialog.setOnShowListener{dialog.getButton(AlertDialog.BUTTON_POSITIVE).setTextColor(blue);dialog.getButton(AlertDialog.BUTTON_NEGATIVE).setTextColor(0xff6b7184.toInt())};dialog.show()}
    private fun welcome(){screen();heading(tr("WELCOME"),34);heading("WE EARN TOGETHER",18,gold);label(tr("Play games, complete missions and build your loyalty progress."),18);val e=EditText(this).apply{hint=tr("PLAYER NAME");setSingleLine(true);setTextColor(Color.WHITE);setHintTextColor(Color.GRAY);setPadding(28,20,28,20);background=rounded(panel,28f)};root.addView(e,LinearLayout.LayoutParams(-1,118).apply{bottomMargin=22});button(tr("CONTINUE")){val n=e.text.toString().trim().ifBlank{tr("PLAYER")};profile.edit().putString("display_name",n).putString("guest_id",java.util.UUID.randomUUID().toString()).putLong("created_at",System.currentTimeMillis()).apply();initAds();home()}}
    private fun markAndOpen(game:String,open:()->Unit){playHistory.mark(game);open()}
    private fun resumeLast(){when(playHistory.lastGame){"bubble"->bubbleShooter();"block"->blockPuzzle();"stack"->neonStack();"lines"->colorLines();"2048"->merge2048();else->gamesHub()}}
    private fun nav(){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;background=rounded(0xff0e1834.toInt(),30f);setPadding(5,5,5,5)};fun item(label:String,action:()->Unit){row.addView(Button(this).apply{text=tr(label);isAllCaps=false;textSize=11f;setTextColor(Color.WHITE);setTypeface(null,Typeface.BOLD);minHeight=0;minimumHeight=0;background=rounded(panel2,20f);setOnClickListener{action()}},LinearLayout.LayoutParams(0,92,1f).apply{setMargins(3,3,3,3)})};item("HOME"){home()};item("GAMES"){gamesHub()};item("QUESTS"){progressDashboard()};item("PROFILE"){account()};root.addView(row,LinearLayout.LayoutParams(-1,112).apply{topMargin=10})}
    private fun progress(game:String)=playHistory.plays(game).coerceAtMost(10)
    private fun home(){screen();val top=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};top.addView(TextView(this).apply{text="WE EARN TOGETHER";textSize=17f;setTextColor(gold);setTypeface(null,Typeface.BOLD)},LinearLayout.LayoutParams(0,70,1f));top.addView(TextView(this).apply{text=profile.getString("display_name",tr("PLAYER"));gravity=Gravity.CENTER;textSize=13f;setTextColor(Color.WHITE);background=rounded(panel,22f);setOnClickListener{account()}},LinearLayout.LayoutParams(210,70));root.addView(top);hero();stats();if(playHistory.lastGame!=null){section(tr("CONTINUE PLAYING"));button(tr("RESUME LAST GAME")){resumeLast()}};section(tr("FEATURED MISSIONS"));missionCard("Bubble Shooter","Clear colorful boards and complete 10 play sessions.","ARCADE",progress("bubble"),10){markAndOpen("bubble"){bubbleShooter()}};missionCard("Block Puzzle","Clear lines, build combos and complete 10 play sessions.","PUZZLE",progress("block"),10){markAndOpen("block"){blockPuzzle()}};section(tr("MORE GAMES"));missionCard("Color Lines","Build lines of five or more on the 9×9 board.","STRATEGY",progress("lines"),10){markAndOpen("lines"){colorLines()}};missionCard("Neon Stack","Time every drop and chase perfect stacks.","ARCADE",progress("stack"),10){markAndOpen("stack"){neonStack()}};nav()}
    private fun gamesHub(){screen(tr("GAME QUESTS"));label(tr("Choose a mission. Progress is saved on this device."));missionCard("Bubble Shooter","Clear colorful boards and complete 10 play sessions.","ARCADE",progress("bubble"),10){markAndOpen("bubble"){bubbleShooter()}};missionCard("Block Puzzle","Clear lines, build combos and complete 10 play sessions.","PUZZLE",progress("block"),10){markAndOpen("block"){blockPuzzle()}};missionCard("Color Lines","Build lines of five or more on the 9×9 board.","STRATEGY",progress("lines"),10){markAndOpen("lines"){colorLines()}};missionCard("Neon Stack","Time every drop and chase perfect stacks.","ARCADE",progress("stack"),10){markAndOpen("stack"){neonStack()}};missionCard("2048","Merge tiles and build your best board.","LOGIC",progress("2048"),10){markAndOpen("2048"){merge2048()}};nav()}
    private fun account(){screen(tr("PROFILE"));heading(profile.getString("display_name",tr("PLAYER"))?:tr("PLAYER"),25,gold);val e=EditText(this).apply{setText(profile.getString("display_name",tr("PLAYER")));setTextColor(Color.WHITE);setSingleLine(true);background=rounded(panel,26f);setPadding(24,10,24,10)};root.addView(e,LinearLayout.LayoutParams(-1,108).apply{bottomMargin=16});button(tr("SAVE NAME")){val n=e.text.toString().trim();if(n.isNotEmpty()){profile.edit().putString("display_name",n).apply();account()}};nav()}
    private fun progressDashboard(){screen(tr("QUESTS"));heading("${loyalty.points} ${tr("LOYALTY")}",30,gold);label("${tr("GAMES")}: ${loyalty.gamesPlayed}   •   ${tr("STREAK")}: ${loyalty.currentStreak}   •   ${tr("BEST")}: ${loyalty.bestStreak}",16);section(tr("GAME MISSIONS"));missionCard("Bubble Shooter","Complete 10 play sessions.","ARCADE",progress("bubble"),10){markAndOpen("bubble"){bubbleShooter()}};missionCard("Block Puzzle","Complete 10 play sessions.","PUZZLE",progress("block"),10){markAndOpen("block"){blockPuzzle()}};section(tr("DAILY JOURNEY"));val done=loyalty.todayGames.coerceAtMost(loyalty.dailyGoal);root.addView(ProgressBar(this,null,android.R.attr.progressBarStyleHorizontal).apply{max=loyalty.dailyGoal;progress=done},LinearLayout.LayoutParams(-1,30).apply{bottomMargin=14});if(loyalty.dailyClaimed)label(tr("Daily bonus already claimed."),16,gold)else if(done>=loyalty.dailyGoal)button(tr("CLAIM 100 LOYALTY")){loyalty.claimDailyChallenge();progressDashboard()};nav()}
    private fun gameShell(title:String,subtitle:String,view:View,restart:()->Unit){screen(title);label(tr(subtitle),15,gold);root.addView(view,LinearLayout.LayoutParams(-1,1350));button(tr("RESTART")){restart()};button(tr("PLAY HUB")){home()}}
    private fun bubbleShooter(){playHistory.mark("bubble");val game=BubbleShooterView(this){levelPlay?.showInterstitialAtNaturalBreak()};gameShell("Bubble Shooter","Aim, shoot and clear the board. Tap NEXT to swap bubbles.",game){game.restart()}}
    private fun colorLines(){playHistory.mark("lines");val game=ColorLinesView(this);gameShell("Color Lines","9×9 strategy. Move balls and create lines of five or more.",game){game.restart()}}
    private fun neonStack(){playHistory.mark("stack");val game=NeonStackView(this);gameShell("Neon Stack","Precision timing. Chase perfect drops and your best score.",game){game.restart()}}
    private fun merge2048(){playHistory.mark("2048");val game=Merge2048View(this);gameShell("2048","Merge tiles and beat your best score.",game){game.restart()}}
    private fun blockPuzzle(){playHistory.mark("block");val game=BlockPuzzleView(this);gameShell("Block Puzzle","Place pieces, clear lines and build combos.",game){game.restart()}}
}
